// src/pages/SignInPage.jsx
import React, { useState, useEffect, useRef } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import axios from "../axiousInstance";
import "./SignInPage.css";

export default function SignInPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const emailRef = useRef(null);
  const from = location.state?.from?.pathname || "/profile";

  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [errors, setErrors] = useState({});
  const [showPassword, setShowPassword] = useState(false);

  useEffect(() => {
    emailRef.current?.focus();
  }, [isLogin]);

  const validateEmail = (email) =>
      /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const newErrors = {};
    const trimmedEmail = email.trim();
    const trimmedPassword = password.trim();

    if (!validateEmail(trimmedEmail)) {
      newErrors.email = "Enter a valid email address";
    }

    if (!trimmedPassword || trimmedPassword.length < 6) {
      newErrors.password = "Password must be at least 6 characters";
    }

    if (!isLogin) {
      if (!firstName.trim()) newErrors.firstName = "First name is required";
      if (!lastName.trim()) newErrors.lastName = "Last name is required";
      if (!confirmPassword.trim()) newErrors.confirmPassword = "Please confirm your password";
      if (trimmedPassword !== confirmPassword.trim()) {
        newErrors.confirmPassword = "Passwords do not match";
      }
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    const userData = isLogin
        ? { email: trimmedEmail, password: trimmedPassword }
        : {
          firstname: firstName.trim(),
          lastname: lastName.trim(),
          email: trimmedEmail,
          password: trimmedPassword,
        };

    try {
      const endpoint = isLogin
          ? "http://localhost:8080/api/auth/login"
          : "http://localhost:8080/api/auth/register";

      const response = await axios.post(endpoint, userData);
      localStorage.setItem("email", trimmedEmail);

      alert(isLogin ? "Logged in successfully!" : "Account created successfully!");
      navigate(from);
    } catch (error) {
      const message = error.response?.data?.message || "Authentication failed.";
      alert(message);
    }
  };

  return (
      <div className="signin-page">
        <div className="signin-container">
          <h1>{isLogin ? "Sign In" : "Create Account"}</h1>
          <form onSubmit={handleSubmit} className="signin-form">
            {!isLogin && (
                <>
                  <input placeholder="First Name" value={firstName} onChange={e => setFirstName(e.target.value)} />
                  <input placeholder="Last Name" value={lastName} onChange={e => setLastName(e.target.value)} />
                </>
            )}
            <input type="email" ref={emailRef} placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} />
            <input type={showPassword ? "text" : "password"} placeholder="Password" value={password} onChange={e => setPassword(e.target.value)} />
            {!isLogin && (
                <input type="password" placeholder="Confirm Password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} />
            )}
            <button type="submit">{isLogin ? "Sign In" : "Create Account"}</button>
            <button type="button" onClick={() => setIsLogin(!isLogin)}>{isLogin ? "Switch to Sign Up" : "Switch to Sign In"}</button>
          </form>
        </div>
      </div>
  );
}
